</template>
<script setup>
import{ref,computed}from'vue';import{onLoad}from'@dcloudio/uni-app';import{coupons}from'../../data/mock';const tab=ref(0),select=ref(false);onLoad(o=>select.value=!!o.select);const filtered=computed(()=>coupons.filter(v=>v.usable===(tab.value===0)));const choose=item=>{if(select.value){uni.setStorageSync('selected_coupon',item);uni.navigateBack()}else uni.switchTab({url:'/pages/home/home'})}
